def max_depth_parentheses(paren_string: str) -> int:
    """ Input to this function is a string represented a single group of nested parentheses separated by space.
    The maximum depth of nested parentheses in the group is output.

    >>> max_depth_parentheses('(()()) ((())) () ((())()())')
    3
    """
    result = 0
    if '(' not in paren_string:
        return result
    else:
        for index in range(len(paren_string)):
            if paren_string[index] == '(':
                result += 1
                continue
            if paren_string[index] == ')':
                result -= 1
                if result < 0:
                    return result
        return result

