def trunc(max_num: int) -> int:
    """Return the number truncated to closest integer depending
    on the given max number.

    If the number is bigger than max number - truncate it down,
    otherwise, truncate up.
    If number is equal to max_num return max_num.
    """
    if number > max_num:
        return max_num - (max_num - number)
    elif number < max_num:
        return number + (max_num - number)
    else:
        return max_num

