def get_fibonacci_number(n: int) -> float:
    """ Return fibonacci sequence of nth number (starting from 1).

    >>> get_fibonacci_number(5)
    5.0
    >>> get_fibonacci_number(8)
    21.0
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return get_fibonacci_number(n-1) + get_fibonacci_number(n-2)

