def deepest_level(paren: str) -> int:
    """ Input to this function is single parentheses represented by one character '(' or ')'.
    Return the deepest level of nesting of parentheses. E.g., ')' has zero levels while '(()())' has one."""
    if len(paren) == 1:
        return 0
    if len(paren) % 2 == 1: # Odd number of brackets - one is extra and needs to be skipped
        return 1
    else:
        count = 0
        for char in paren:
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
        return count + 1

